#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "common.h"
#include "shaders_from_files.h"

#define MIN_SIZE           (1 << 16)
#define MAX_SIZE           (1 << 28)
#define SIZE_LSHIFT_STEP   2

/* The typical size of all memory requests generated by each test. This determines the execution
 * time, though small sizes are also capped by MAX_RUNS.
 */
#define EXECUTION_SIZE     (256 * 1024 * 1024)
#define MAX_RUNS           4096

#define MAX_FB_SETS        ((LOG2_POT(MAX_SIZE) - LOG2_POT(MIN_SIZE)) / SIZE_LSHIFT_STEP + 1)
#define MAX_RING_SIZE      (MAX_FB_SETS * MAX_SIZE / MIN_SIZE)
#define MAX_DELETE_ITEMS   (128 * MAX_RING_SIZE)
#define MAX_DESC_SETS      (4 * MAX_FB_SETS)

#define DEBUG_DUMP_IMAGES  0

#define SQRT_2             1.414213562

typedef struct {
   const char *name;
   unsigned num_color_attachments;
   VkFormat color_format;
   VkFormat zs_format;
} test_formats;

static const test_formats formats[] = {
   {"r8",                  1, VK_FORMAT_R8_UNORM},
   {"r16f",                1, VK_FORMAT_R16_SFLOAT},
   {"rgba8",               1, VK_FORMAT_R8G8B8A8_UNORM},
   {"rgba8_d32s8",         1, VK_FORMAT_R8G8B8A8_UNORM, VK_FORMAT_D32_SFLOAT_S8_UINT},
   {"rgba8_d32s8_4mrt",    4, VK_FORMAT_R8G8B8A8_UNORM, VK_FORMAT_D32_SFLOAT_S8_UINT},
   {"rgba16f",             1, VK_FORMAT_R16G16B16A16_SFLOAT},
   {"rgba16f_d32s8",       1, VK_FORMAT_R16G16B16A16_SFLOAT, VK_FORMAT_D32_SFLOAT_S8_UINT},
   {"rgba16f_d32s8_4mrt",  4, VK_FORMAT_R16G16B16A16_SFLOAT, VK_FORMAT_D32_SFLOAT_S8_UINT},
   {"rgba32f",             1, VK_FORMAT_R32G32B32A32_SFLOAT},
   {"d32",                 0, 0, VK_FORMAT_D32_SFLOAT},
   {"s8",                  0, 0, VK_FORMAT_S8_UINT},
   {"d32s8",               0, 0, VK_FORMAT_D32_SFLOAT_S8_UINT},
};

typedef struct {
   api_shader *vs_passthrough[2]; /* layered / non-layered variants */
   api_shader *vs_gen_triangles[2]; /* layered / non-layered variants */
   api_shader *fs_gradient[7]; /* output format variants */
   api_shader *fs_random[10]; /* output format variants */
   api_shader *fs_solid[ARRAY_SIZE(formats)];
   api_shader *fs_color_passthrough_fs[ARRAY_SIZE(formats)];
   api_shader *fs_fragpos_texture_fs[ARRAY_SIZE(formats)];

   api_descriptor_set_layout *layout_draw_triangles;
   api_gfx_pipeline *pipeline_draw_solid[MAX_FB_SETS];
   api_gfx_pipeline *pipeline_draw_triangles[MAX_FB_SETS][2]; /* color passthrough / textured */

   api_gfx_pipeline *delete_pipelines[MAX_DELETE_ITEMS];
   unsigned num_delete_items;

   api_buffer *ubo;
   api_descriptor_set *desc_draw_triangles[MAX_DESC_SETS];
   bool reset_desc[MAX_DESC_SETS];

   api_image *random_texture;
   api_sampler *sampler;

   const void *shader_param_regexs_vs_quad;
   const void *shader_param_regexs_vs_gen_triangles;
   const void *shader_param_regexs_fs_mrt;
   const void *shader_param_regexs_fs_gradient;
   const void *shader_param_regexs_fs_random;
} misc_state;

static api_shader *
get_passthrough_vs(api_context *ctx, misc_state *state, bool layered)
{
   api_shader **vs = &state->vs_passthrough[layered];

   if (*vs)
      return *vs;

   static const char *shader_params[] = {
      [0] = "layered",
   };

   if (!state->shader_param_regexs_vs_quad) {
      state->shader_param_regexs_vs_quad =
         compile_shader_param_regexs(shader_params, ARRAY_SIZE(shader_params));
   }

   replacement_value values[ARRAY_SIZE(shader_params)] = {
      [0] = {.uint64 = layered},
   };

   char source[1000];
   regex_replace(source, sizeof(source), imgbw_quad_vert, state->shader_param_regexs_vs_quad,
                 ARRAY_SIZE(shader_params), values);

   *vs = ctx->create_shader(ctx, source, api_shader_vs);
   return *vs;
}

static api_shader *
get_gen_triangles_vs(api_context *ctx, misc_state *state, bool layered)
{
   api_shader **vs = &state->vs_gen_triangles[layered];

   if (*vs)
      return *vs;

   static const char *shader_params[] = {
      [0] = "layered",
   };

   if (!state->shader_param_regexs_vs_gen_triangles) {
      state->shader_param_regexs_vs_gen_triangles =
         compile_shader_param_regexs(shader_params, ARRAY_SIZE(shader_params));
   }

   replacement_value values[ARRAY_SIZE(shader_params)] = {
      [0] = {.uint64 = layered},
   };

   char source[2400];
   regex_replace(source, sizeof(source), gen_triangles_vert,
                 state->shader_param_regexs_vs_gen_triangles, ARRAY_SIZE(shader_params), values);

   *vs = ctx->create_shader(ctx, source, api_shader_vs);
   return *vs;
}

static api_shader *
get_gradient_fs(api_context *ctx, misc_state *state, VkFormat format)
{
   bool has_color_output = !format_is_depth_or_stencil(format);
   bool has_stencil_output = format_has_stencil(format);
   bool is_sint = has_color_output && format_is_sint(format);
   bool is_integer = has_color_output && format_is_integer(format);
   unsigned chan_size = has_color_output ? get_pixel_size_from_format(format) /
                                           format_get_num_channels(format) : 0;
   const char *gradient, *vec_type;
   unsigned format_index;

   /* This fragment shader code generates the gradient pattern. */
   if (is_integer) {
      if (chan_size == 1) {
         if (is_sint) {
            gradient = "int(gl_FragCoord.x) % 128";
            vec_type = "ivec4";
            format_index = 0;
         } else {
            gradient = "uint(gl_FragCoord.x) % 256";
            vec_type = "uvec4";
            format_index = 1;
         }
      } else if (chan_size >= 2) {
         if (is_sint) {
            gradient = "int(gl_FragCoord.x)";
            vec_type = "ivec4";
            format_index = 2;
         } else {
            gradient = "uint(gl_FragCoord.x)";
            vec_type = "uvec4";
            format_index = 3;
         }
      } else {
         error("invalid chan size");
      }
   } else {
      gradient = "mod(gl_FragCoord.x, 256.0) / 256.0";
      vec_type = "";

      if (has_color_output) {
         vec_type = "vec4";
         format_index = 4;
      } else if (has_stencil_output) {
         format_index = 5;
      } else {
         /* The Z gradient is drawn via VS position.z. */
         assert(format_has_depth(format));
         format_index = 6;
      }
   }

   assert(format_index < ARRAY_SIZE(state->fs_gradient));
   api_shader **fs = &state->fs_gradient[format_index];

   if (*fs)
      return *fs;

   static const char *shader_params[] = {
      [0] = "has_color_output",
      [1] = "has_stencil_output",
      [2] = "vec_type",
      [3] = "gradient",
   };

   if (!state->shader_param_regexs_fs_gradient) {
      state->shader_param_regexs_fs_gradient =
         compile_shader_param_regexs(shader_params, ARRAY_SIZE(shader_params));
   }

   replacement_value values[ARRAY_SIZE(shader_params)] = {
      [0] = {.uint64 = has_color_output},
      [1] = {.uint64 = has_stencil_output},
      [2] = {.string = vec_type},
      [3] = {.string = gradient},
   };

   char source[1000];
   regex_replace(source, sizeof(source), imgbw_gradient_frag, state->shader_param_regexs_fs_gradient,
                 ARRAY_SIZE(shader_params), values);

   *fs = ctx->create_shader(ctx, source, api_shader_fs);
   return *fs;
}

static const char *
get_vec_type(VkFormat format)
{
   return format_is_sint(format) ? "ivec4" : format_is_integer(format) ? "uvec4" : "vec4";
}

static unsigned
get_fs_output_value_multiplier(api_image *cb)
{
   if (!cb || !format_is_integer(cb->format))
      return 1;

   const unsigned bpc = get_pixel_size_from_format(cb->format) / format_get_num_channels(cb->format);
   const unsigned log_bpc = LOG2_POT(bpc);

   static const unsigned uint_multiplier[] = {
      UINT8_MAX,
      UINT16_MAX,
      UINT32_MAX,
   };

   static const unsigned sint_multiplier[] = {
      INT8_MAX,
      INT16_MAX,
      UINT32_MAX,
   };
   assert(log_bpc < 3);

   if (format_is_sint(cb->format))
      return sint_multiplier[log_bpc];
   else
      return uint_multiplier[log_bpc];
}

static api_shader *
get_fs(api_context *ctx, misc_state *state, api_framebuffer *fb, unsigned fb_config_index,
       api_shader **fs, const char *code)
{
   if (*fs)
      return *fs;

   static const char *shader_params[] = {
      [0] = "n",
      [1] = "vec_type0",
      [2] = "vec_type1",
      [3] = "vec_type2",
      [4] = "vec_type3",
      [5] = "0_is_integer",
      [6] = "1_is_integer",
      [7] = "2_is_integer",
      [8] = "3_is_integer",
      [9] = "multiplier0",
      [10] = "multiplier1",
      [11] = "multiplier2",
      [12] = "multiplier3",
   };

   if (!state->shader_param_regexs_fs_mrt) {
      state->shader_param_regexs_fs_mrt =
         compile_shader_param_regexs(shader_params, ARRAY_SIZE(shader_params));
   }

   replacement_value values[ARRAY_SIZE(shader_params)] = {
      [0] = {.uint64 = fb->num_color_attachments},
      [1] = {.string = fb->colorbufs[0] ? get_vec_type(fb->colorbufs[0]->format) : ""},
      [2] = {.string = fb->colorbufs[1] ? get_vec_type(fb->colorbufs[1]->format) : ""},
      [3] = {.string = fb->colorbufs[2] ? get_vec_type(fb->colorbufs[2]->format) : ""},
      [4] = {.string = fb->colorbufs[3] ? get_vec_type(fb->colorbufs[3]->format) : ""},
      [5] = {.uint64 = fb->colorbufs[0] && format_is_integer(fb->colorbufs[0]->format)},
      [6] = {.uint64 = fb->colorbufs[1] && format_is_integer(fb->colorbufs[1]->format)},
      [7] = {.uint64 = fb->colorbufs[2] && format_is_integer(fb->colorbufs[2]->format)},
      [8] = {.uint64 = fb->colorbufs[3] && format_is_integer(fb->colorbufs[3]->format)},
      [9] = {.uint64 = get_fs_output_value_multiplier(fb->colorbufs[0])},
      [10] = {.uint64 = get_fs_output_value_multiplier(fb->colorbufs[1])},
      [11] = {.uint64 = get_fs_output_value_multiplier(fb->colorbufs[2])},
      [12] = {.uint64 = get_fs_output_value_multiplier(fb->colorbufs[3])},
   };

   char source[1000];
   regex_replace(source, sizeof(source), code, state->shader_param_regexs_fs_mrt,
                 ARRAY_SIZE(shader_params), values);

   *fs = ctx->create_shader(ctx, source, api_shader_fs);
   return *fs;
}

static api_shader *
get_solid_color_fs(api_context *ctx, misc_state *state, api_framebuffer *fb, unsigned fb_config_index)
{
   assert(fb_config_index < ARRAY_SIZE(state->fs_solid));

   return get_fs(ctx, state, fb, fb_config_index, &state->fs_solid[fb_config_index], imgbw_solid_frag);
}

static api_shader *
get_color_passthrough_fs(api_context *ctx, misc_state *state, api_framebuffer *fb,
                         unsigned fb_config_index)
{
   assert(fb_config_index < ARRAY_SIZE(state->fs_color_passthrough_fs));

   return get_fs(ctx, state, fb, fb_config_index, &state->fs_color_passthrough_fs[fb_config_index],
                 imgbw_color_passthrough_frag);
}

static api_shader *
get_fragpos_texture_fs(api_context *ctx, misc_state *state, api_framebuffer *fb,
                       unsigned fb_config_index)
{
   assert(fb_config_index < ARRAY_SIZE(state->fs_fragpos_texture_fs));

   return get_fs(ctx, state, fb, fb_config_index, &state->fs_fragpos_texture_fs[fb_config_index],
                 imgbw_fragpos_texture_frag);
}

static api_shader *
get_random_pixel_fs(api_context *ctx, misc_state *state, VkFormat format)
{
   bool has_color_output = !format_is_depth_or_stencil(format);
   bool has_depth_output = format_has_depth(format);
   bool has_stencil_output = format_has_stencil(format);
   bool is_sint = has_color_output && format_is_sint(format);
   bool is_integer = has_color_output && format_is_integer(format);
   unsigned chan_size = has_color_output ? get_pixel_size_from_format(format) /
                                           format_get_num_channels(format) : 0;
   const char *rand_color, *vec_type;
   unsigned format_index;

   /* This fragment shader code generates the gradient pattern. */
   if (is_integer) {
      if (chan_size == 1) {
         if (is_sint) {
            rand_color = "rand_uvec4(seed) >> 25";
            vec_type = "ivec4";
            format_index = 0;
         } else {
            rand_color = "rand_uvec4(seed) >> 24";
            vec_type = "uvec4";
            format_index = 1;
         }
      } else if (chan_size == 2) {
         if (is_sint) {
            rand_color = "rand_uvec4(seed) >> 17";
            vec_type = "ivec4";
            format_index = 2;
         } else {
            rand_color = "rand_uvec4(seed) >> 16";
            vec_type = "uvec4";
            format_index = 3;
         }
      } else if (chan_size == 4) {
         if (is_sint) {
            rand_color = "rand_uvec4(seed) >> 1";
            vec_type = "ivec4";
            format_index = 4;
         } else {
            rand_color = "rand_uvec4(seed)";
            vec_type = "uvec4";
            format_index = 5;
         }
      } else {
         error("invalid chan size");
      }
   } else {
      rand_color = "";
      vec_type = "";

      if (has_color_output) {
         rand_color = "rand_vec4(seed)";
         vec_type = "vec4";
         format_index = 6;
      } else if (has_depth_output && has_stencil_output) {
         format_index = 7;
      } else if (has_stencil_output) {
         format_index = 8;
      } else {
         assert(format_has_depth(format));
         format_index = 9;
      }
   }

   assert(format_index < ARRAY_SIZE(state->fs_random));
   api_shader **fs = &state->fs_random[format_index];

   if (*fs)
      return *fs;

   static const char *shader_params[] = {
      [0] = "has_color_output",
      [1] = "has_depth_output",
      [2] = "has_stencil_output",
      [3] = "vec_type",
      [4] = "expr",
   };

   if (!state->shader_param_regexs_fs_random) {
      state->shader_param_regexs_fs_random =
         compile_shader_param_regexs(shader_params, ARRAY_SIZE(shader_params));
   }

   replacement_value values[ARRAY_SIZE(shader_params)] = {
      [0] = {.uint64 = has_color_output},
      [1] = {.uint64 = has_depth_output},
      [2] = {.uint64 = has_stencil_output},
      [3] = {.string = vec_type},
      [4] = {.string = rand_color},
   };

   char source[2000];
   regex_replace(source, sizeof(source), imgbw_random_frag, state->shader_param_regexs_fs_random,
                 ARRAY_SIZE(shader_params), values);

   *fs = ctx->create_shader(ctx, source, api_shader_fs);
   return *fs;
}

static void
generate_pixels(api_context *ctx, misc_state *state, api_image *image, api_framebuffer *fb,
                api_shader *fs, unsigned samplemask)
{
   bool layered = image->depth > 1;
   api_shader *vs = get_passthrough_vs(ctx, state, layered);
   api_gfx_pipeline *pipeline =
      ctx->create_gfx_pipeline(ctx,
                               &(api_gfx_pipeline_desc){
                                  .topology = VK_PRIMITIVE_TOPOLOGY_TRIANGLE_STRIP,
                                  .vs = vs,
                                  .fs = fs,
                                  .vrs_fragment_size = {1, 1},
                                  .samplemask = samplemask,
                                  .colormask = 0xf,
                                  .depth_enabled = true,
                                  .depth_write_enabled = true,
                                  .depth_compare_op = VK_COMPARE_OP_ALWAYS,
                                  /* The FS stencil output should overwrite stencil. */
                                  .stencil_enabled = true,
                                  .stencil_front.passOp = VK_STENCIL_OP_REPLACE,
                                  .stencil_front.compareOp = VK_COMPARE_OP_ALWAYS,
                                  .stencil_front.writeMask = 0xff,
                                  .stencil_back.passOp = VK_STENCIL_OP_REPLACE,
                                  .stencil_back.compareOp = VK_COMPARE_OP_ALWAYS,
                                  .stencil_back.writeMask = 0xff,
                                  .fb = fb,
                               });

   ctx->begin_cmdbuf(ctx, api_queue_gfx);
   ctx->begin_render_pass(ctx, &(api_render_pass_desc){.fb = fb});

   ctx->bind_gfx_pipeline(ctx, pipeline);
   ctx->draw(ctx, &(api_draw_desc){.count = 4, .instance_count = layered ? image->depth : 1});

   ctx->end_render_pass(ctx);
   ctx->barrier_images(ctx, 1, &image, false, api_queue_gfx, api_queue_gfx);
   ctx->end_cmdbuf_and_submit(ctx, api_wait_all_queues, NULL, NULL);

   assert(state->num_delete_items < ARRAY_SIZE(state->delete_pipelines));
   state->delete_pipelines[state->num_delete_items] = pipeline;
   state->num_delete_items++;
}

static void
set_gradient_pixels(api_context *ctx, misc_state *state, api_image *image, api_framebuffer *fb)
{
   generate_pixels(ctx, state, image, fb, get_gradient_fs(ctx, state, image->format),
                   (1 << image->samples) - 1);
}

static void
set_random_pixels(api_context *ctx, misc_state *state, api_image *image, api_framebuffer *fb,
                  unsigned samplemask)
{
   generate_pixels(ctx, state, image, fb, get_random_pixel_fs(ctx, state, image->format), samplemask);
}

static void
draw_solid(api_context *ctx, misc_state *state, api_framebuffer *fb, unsigned fb_set,
           unsigned fb_config_index)
{
   bool layered = fb->layers > 1;
   api_shader *vs = get_passthrough_vs(ctx, state, layered);
   api_shader *fs = get_solid_color_fs(ctx, state, fb, fb_config_index);
   api_gfx_pipeline **pipeline = &state->pipeline_draw_solid[fb_set];

   if (!*pipeline) {
      *pipeline = ctx->create_gfx_pipeline(ctx,
                                           &(api_gfx_pipeline_desc){
                                              .topology = VK_PRIMITIVE_TOPOLOGY_TRIANGLE_STRIP,
                                              .vs = vs,
                                              .fs = fs,
                                              .vrs_fragment_size = {1, 1},
                                              .samplemask = ~0,
                                              .colormask = 0xf,
                                              .depth_enabled = true,
                                              .depth_write_enabled = true,
                                              .depth_compare_op = VK_COMPARE_OP_ALWAYS,
                                              .stencil_enabled = true,
                                              .stencil_front.passOp = VK_STENCIL_OP_REPLACE,
                                              .stencil_front.compareOp = VK_COMPARE_OP_ALWAYS,
                                              .stencil_front.writeMask = 0xff,
                                              .stencil_front.reference = 0x89,
                                              .stencil_back.passOp = VK_STENCIL_OP_REPLACE,
                                              .stencil_back.compareOp = VK_COMPARE_OP_ALWAYS,
                                              .stencil_back.writeMask = 0xff,
                                              .stencil_back.reference = 0x89,
                                              .fb = fb,
                                           });
   }

   ctx->bind_gfx_pipeline(ctx, *pipeline);
   ctx->draw(ctx, &(api_draw_desc){.count = 4, .instance_count = fb->layers});
}

static void
draw_triangles(api_context *ctx, misc_state *state, bool textured, unsigned triangle_size_index,
               api_framebuffer *fb, unsigned fb_set, unsigned fb_config_index)
{
   static const unsigned triangle_sizes[4] = {
      32 * 32,
      16 * 16,
      8 * 8,
      4 * 4,
   };
   assert(triangle_size_index < ARRAY_SIZE(triangle_sizes));
   const unsigned pixels_per_triangle = triangle_sizes[triangle_size_index];
   const bool layered = fb->layers > 1;
   api_shader *vs = get_gen_triangles_vs(ctx, state, layered);
   api_shader *fs = textured ? get_fragpos_texture_fs(ctx, state, fb, fb_config_index) :
                               get_color_passthrough_fs(ctx, state, fb, fb_config_index);
   api_gfx_pipeline **pipeline = &state->pipeline_draw_triangles[fb_set][textured];

   if (!state->layout_draw_triangles) {
      state->layout_draw_triangles =
         ctx->create_descriptor_set_layout(ctx, &(api_descriptor_set_layout_desc){
                                              .uniform_buffer[0].array_size = 1,
                                              .combined_image_sampler[0].array_size = 1,
                                              .combined_image_sampler[0].vk_binding = 1,
                                           });
   }

   if (!state->random_texture) {
      /* Create a random noise texture that will be used to generate a texture-like pattern
       * in the fragment shader.
       */
      const unsigned width = 128;

      state->random_texture =
         ctx->create_image(ctx, VK_IMAGE_TYPE_2D, VK_FORMAT_R8G8B8A8_UNORM,
                           width, width, 1, 1, VK_IMAGE_TILING_OPTIMAL,
                           api_heap_device,
                           VK_IMAGE_USAGE_TRANSFER_DST_BIT |
                           VK_IMAGE_USAGE_SAMPLED_BIT, VK_IMAGE_LAYOUT_UNDEFINED);

      srand(0x1263c379);

      char *img_data = malloc(width * width * 4);
      for (unsigned y = 0; y < width; y++) {
         for (unsigned x = 0; x < width; x++) {
            char *pix = &img_data[(y * width + x) * 4];

            pix[0] = rand() % 256;
            pix[1] = rand() % 256;
            pix[2] = rand() % 256;
            pix[3] = rand() % 256;
         }
      }

      ctx->upload_image_data(ctx, api_queue_gfx, state->random_texture, 0, width * 4, img_data);
      free(img_data);

      state->sampler = ctx->create_sampler(ctx, &(api_sampler_desc){
                                              .min_filter = VK_FILTER_LINEAR,
                                              .mag_filter = VK_FILTER_LINEAR,
                                              .wrap_u = VK_SAMPLER_ADDRESS_MODE_REPEAT,
                                              .wrap_v = VK_SAMPLER_ADDRESS_MODE_REPEAT,
                                           });
   }

   const unsigned desc_index = triangle_size_index * MAX_FB_SETS + fb_set;
   api_descriptor_set **set = &state->desc_draw_triangles[desc_index];

   if (!*set || state->reset_desc[desc_index]) {
      /* The shader generates equilateral triangles at random positions with the triangle circumradius
       * in X,Y axes as inputs. (X != Y when width != height for aspect correction).
       *
       * An equilateral triangle has:
       *    area = (3 * sqrt(3) / 4) * radius²
       * That implies:
       *    sqrt(4 * area / (3 * sqrt(3))) = radius
       */
      const float radius_pixels = sqrtf(4.f * pixels_per_triangle / (3.f * sqrtf(3.f)));

      const uint32_t vs_uniforms[4] = {
         fui(2.f * radius_pixels / fb->width),
         fui(2.f * radius_pixels / fb->height),
         fb->layers,
      };

      const unsigned ubo_upload_size = MAX2(sizeof(vs_uniforms), ctx->uniform_buffer_alignment);

      if (!state->ubo)
         state->ubo = ctx->create_buffer(ctx, MAX_DESC_SETS * ubo_upload_size, api_heap_device, 0);

      /* Upload the UBO data. */
      unsigned ubo_offset = desc_index * ubo_upload_size;
      assert(ubo_offset + sizeof(vs_uniforms) <= state->ubo->size);
      assert(desc_index < ARRAY_SIZE(state->desc_draw_triangles));

      ctx->upload_buffer_data(ctx, api_queue_gfx, state->ubo, ubo_offset, sizeof(vs_uniforms),
                              vs_uniforms);

      /* Prepare the descriptor set. */
      if (!*set)
         *set = ctx->create_descriptor_set(ctx, state->layout_draw_triangles);

      ctx->set_uniform_buffer_descriptor(ctx, *set, 0, state->ubo, ubo_offset, sizeof(vs_uniforms));
      ctx->set_combined_image_sampler_descriptors(ctx, api_queue_gfx, *set, 0, 1,
                                                  &state->random_texture, &state->sampler);
      state->reset_desc[desc_index] = false;
   }

   /* Create the pipeline. */
   if (!*pipeline) {
      *pipeline = ctx->create_gfx_pipeline(ctx,
                                           &(api_gfx_pipeline_desc){
                                              .topology = VK_PRIMITIVE_TOPOLOGY_TRIANGLE_LIST,
                                              .desc_set_layout = state->layout_draw_triangles,
                                              .vs = vs,
                                              .fs = fs,
                                              .vrs_fragment_size = {1, 1},
                                              .samplemask = ~0,
                                              .colormask = 0xf,
                                              .depth_enabled = true,
                                              .depth_write_enabled = true,
                                              .depth_compare_op = VK_COMPARE_OP_ALWAYS,
                                              .fb = fb,
                                           });
   }

   /* Calculate the number of triangles from how much overdraw we want.
    *
    * Due to the random placement of triangles, some areas may stay cleared while others may get
    * triangles on top of each other. overdraw_amount = 2 and 3 leaves about 13.5% and 5% uncovered
    * (e^-2 and e^-3), respectively.
    */
   const double overdraw_amount = 3;
   const double fb_area = (double)fb->width * fb->height * fb->layers;
   const unsigned num_triangles = ceil(overdraw_amount * fb_area / pixels_per_triangle);

   ctx->begin_cmdbuf(ctx, api_queue_gfx);
   ctx->begin_render_pass(ctx, &(api_render_pass_desc) {
                             .fb = fb,
                             .clear = true,
                          });
   ctx->bind_descriptor_set(ctx, *set);
   ctx->bind_gfx_pipeline(ctx, *pipeline);
   ctx->draw(ctx, &(api_draw_desc){.count = num_triangles * 3, .instance_count = 1});
   ctx->end_render_pass(ctx);

   /* Execute an image barrier. */
   /*api_image *images[9];
   unsigned num_images = 0;

   for (unsigned i = 0; i < fb->num_color_attachments; i++)
      images[num_images++] = fb->colorbufs[i];

   if (fb->zsbuf)
      images[num_images++] = fb->zsbuf;

   ctx->barrier_images(ctx, num_images, images, false, api_queue_gfx, ctx->options.queue);*/
   ctx->end_cmdbuf_and_submit(ctx, api_wait_all_queues, NULL, NULL);
}

